CREATE TABLE rm_workspace_service_principal_operation_events (
  id INTEGER PRIMARY KEY,
  operation_id TEXT NOT NULL CHECK(length(operation_id)=36),
  operation_type TEXT NOT NULL CHECK(operation_type IN ('create','rotate','revoke')),
  operation_status TEXT NOT NULL CHECK(operation_status IN ('pending','recovering','completed','failed','recovered')),
  user_id TEXT NOT NULL,
  credential_id TEXT,
  replacement_credential_id TEXT,
  provider_operation_marker TEXT NOT NULL CHECK(length(trim(provider_operation_marker))=32),
  recovery_claim_id TEXT CHECK(recovery_claim_id IS NULL OR length(recovery_claim_id)=36),
  actor TEXT NOT NULL CHECK(length(trim(actor)) BETWEEN 3 AND 160),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK((operation_type='create' AND (operation_status!='completed' OR length(trim(credential_id)) > 0)) OR (operation_type IN ('rotate','revoke') AND length(trim(credential_id)) > 0)),
  CHECK((operation_status='recovering' AND length(trim(recovery_claim_id))=36) OR operation_status!='recovering'),
  CHECK((operation_status='completed' AND (operation_type='revoke' OR length(trim(replacement_credential_id)) > 0)) OR operation_status!='completed')
);
CREATE INDEX rm_workspace_service_principal_operation_events_operation_idx ON rm_workspace_service_principal_operation_events(operation_id,id DESC);
CREATE INDEX rm_workspace_service_principal_operation_events_marker_idx ON rm_workspace_service_principal_operation_events(provider_operation_marker);
CREATE TRIGGER rm_workspace_service_principal_operation_events_no_update BEFORE UPDATE ON rm_workspace_service_principal_operation_events BEGIN SELECT RAISE(ABORT, 'workspace service principal operation events are append-only'); END;
CREATE TRIGGER rm_workspace_service_principal_operation_events_no_delete BEFORE DELETE ON rm_workspace_service_principal_operation_events BEGIN SELECT RAISE(ABORT, 'workspace service principal operation events are append-only'); END;
